import json, os, re
from collections import Counter
def f(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    bg=cnt.most_common(1)[0][0]
    sep_rows=[i for i in range(H) if bg not in inp[i]]
    sep_cols=[j for j in range(W) if all(bg not in [inp[r][j] for r in range(H)])]
    linevals={}
    for r in sep_rows:
        vals=Counter(inp[r]); linevals[r]=vals.most_common(1)[0][0]
    out=[]
    for a,b in zip(sep_rows[:-1],sep_rows[1:]):
        row=[]
        for c,d in zip(sep_cols[:-1],sep_cols[1:]):
            cs=[inp[a][c],inp[a][d],inp[b][c],inp[b][d]]
            dom={linevals.get(r_,bg) for r_ in (a,b)}
            # corners that are on the separator lines with their line color count as "no anomaly"
            good=True; v=None
            for x in cs:
                if x in dom and x!=v: good=False; break
                if x not in dom:
                    if v is None: v=x
                elif v is None: v=x
            if good and v is not None: row.append(v)
            else: row.append(bg)
        out.append(row)
    return out
